text:
Here's a water tracker with a goal of 8 glasses. Tap + for each glass, and it saves on this device and starts fresh each day.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: sans-serif; text-align: center; padding: 20px; }
  h1 { font-size: 20px; margin: 0 0 4px; }
  #date { color: #666; font-size: 13px; margin-bottom: 16px; }
  #count { font-size: 48px; font-weight: bold; }
  #msg { margin: 8px 0 16px; min-height: 20px; }
  #glasses { display: flex; justify-content: center; gap: 8px; flex-wrap: wrap; margin-bottom: 20px; }
  .g { width: 28px; height: 40px; border: 2px solid #3b82f6; border-radius: 4px 4px 8px 8px; }
  .g.full { background: #3b82f6; }
  button { font-size: 18px; padding: 10px 20px; margin: 4px; border-radius: 8px; border: 1px solid #3b82f6; background: #fff; cursor: pointer; }
  button.main { background: #3b82f6; color: #fff; }
</style>
</head>
<body>
  <h1>Water today</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="msg"></div>
  <div id="glasses"></div>
  <button class="main" onclick="change(1)">+ Glass</button>
  <button onclick="change(-1)">- Glass</button>
  <button onclick="reset()">Reset</button>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var n = 0;
  try {
    var saved = JSON.parse(localStorage.getItem("water") || "{}");
    if (saved.day === today) n = saved.n || 0;
  } catch (e) {}
  document.getElementById("date").textContent = new Date().toDateString();

  function save() {
    try { localStorage.setItem("water", JSON.stringify({ day: today, n: n })); } catch (e) {}
  }
  function change(d) { n = Math.max(0, n + d); save(); draw(); }
  function reset() { n = 0; save(); draw(); }
  function draw() {
    document.getElementById("count").textContent = n + " / " + GOAL;
    var box = document.getElementById("glasses");
    box.innerHTML = "";
    for (var i = 0; i < GOAL; i++) {
      var d = document.createElement("div");
      d.className = "g" + (i < n ? " full" : "");
      box.appendChild(d);
    }
    var m = document.getElementById("msg");
    if (n >= GOAL) m.textContent = "Goal reached. Well hydrated! 💧";
    else m.textContent = (GOAL - n) + " more to go";
  }
  draw();
</script>
</body>
</html>
```

